const m = $input.first().json.message;

if (!m || typeof m.text !== 'string') return [];

const text = m.text.trim();
if (text.length <= 3 || text.startsWith('/')) return [];

return [{
  json: {
    chatId: m.chat.id,
    userName: (m.from && m.from.first_name) || 'there',
    text
  }
}];

// Money math stays OUT of the LLM. Models are unreliable at arithmetic.

const src = $('Extract Message Details').first().json;

let raw = $input.first().json.output ?? $input.first().json;
if (typeof raw === 'string') {
  try { raw = JSON.parse(raw.replace(/^```[a-z]*/i, '').replace(/```$/, '').trim()); }
  catch (e) { raw = {}; }
}
const p = raw || {};

const destination = String(p.destination || '').trim();
const days = Number(p.days) || 0;
const budget = Number(p.budget) || 0;
const currency = String(p.currency || 'MAD').toUpperCase();
const travellers = Math.max(1, Number(p.travellers) || 1);
const travelStyle = ['budget', 'comfort', 'luxury'].includes(p.travelStyle) ? p.travelStyle : 'comfort';
const interests = Array.isArray(p.interests) ? p.interests : [];

const missing = [];
if (!destination) missing.push('destination');
if (days <= 0) missing.push('number of days');
if (budget <= 0) missing.push('budget');

const nights = Math.max(0, days - 1);
const SPLIT = { stay: 0.40, food: 0.30, activities: 0.20, transport: 0.10 };
const round = (n) => Math.round(n);

const allocation = {
  stayTotal: round(budget * SPLIT.stay),
  stayPerNight: nights > 0 ? round((budget * SPLIT.stay) / nights) : 0,
  foodTotal: round(budget * SPLIT.food),
  foodPerDay: days > 0 ? round((budget * SPLIT.food) / days) : 0,
  activitiesTotal: round(budget * SPLIT.activities),
  activitiesPerDay: days > 0 ? round((budget * SPLIT.activities) / days) : 0,
  transportTotal: round(budget * SPLIT.transport)
};

const planPrompt = [
  `Plan a ${days}-day trip to ${destination} for ${travellers} traveller(s).`,
  `Total budget: ${budget} ${currency}. Travel style: ${travelStyle}.`,
  interests.length ? `Interests: ${interests.join(', ')}.` : 'No stated interests.',
  '',
  'BUDGET TARGET — aim to use 85-95% of the total. Under-spending is a failure, not a saving.',
'If the plan lands under 80% of the budget, upgrade: better accommodation, a paid guided activity, or a nicer dinner.',
  `- Accommodation: about ${allocation.stayPerNight} ${currency} per night, ${nights} night(s).`,
  `- Food: about ${allocation.foodPerDay} ${currency} per day.`,
  `- Activities: about ${allocation.activitiesPerDay} ${currency} per day.`,
  `- Local transport: about ${allocation.transportTotal} ${currency} total.`,
  '',
  `Use the search tool to find REAL, currently operating places in ${destination}. Search before naming anything.`,
  'Never invent a venue. If you cannot verify one, describe the type of place instead and set verified to false.',
  'All prices are estimates. Keep every note under 15 words.'
].join('\n');

return [{
  json: {
    destination, days, nights, budget, currency, travellers, travelStyle, interests,
    allocation,
    missing,
    isComplete: missing.length === 0,
    chatId: src.chatId,
    userName: src.userName,
    planPrompt
  }
}];

let raw = $input.first().json.output ?? $input.first().json;
if (typeof raw === 'string') {
  try { raw = JSON.parse(raw.replace(/^```[a-z]*/i, '').replace(/```$/, '').trim()); }
  catch (e) { raw = null; }
}

const ctx = $('Calculate Budget Details').first().json;
const cur = ctx.currency;
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

if (!raw || !Array.isArray(raw.days) || raw.days.length === 0) {
  return [{ json: {
    chatId: ctx.chatId,
    telegramMessage: 'I could not build the itinerary this time. Send the request again and I will retry.'
  } }];
}

const L = [];
L.push(`<b>${esc(raw.destination || ctx.destination).toUpperCase()}</b>`);
L.push(`${ctx.days} days · ${ctx.travellers} traveller(s) · ${ctx.budget} ${cur}`);
L.push('');

const stay = raw.stay || {};
L.push('<b>WHERE TO STAY</b>');
L.push(`${esc(stay.name)}${stay.area ? ' — ' + esc(stay.area) : ''}`);
if (stay.pricePerNight) L.push(`~${stay.pricePerNight} ${cur}/night · budget allows ~${ctx.allocation.stayPerNight}`);
if (stay.why) L.push(`<i>${esc(stay.why)}</i>`);
if (stay.verified === false) L.push('<i>⚠️ unverified — check availability yourself</i>');
L.push('');

raw.days.sort((a, b) => (a.dayNumber || 0) - (b.dayNumber || 0));

for (const d of raw.days) {
  L.push(`<b>DAY ${d.dayNumber}${d.area ? ' · ' + esc(d.area) : ''}</b>`);
  if (d.morning)   L.push(`🌅 ${esc(d.morning)}`);
  if (d.lunch)     L.push(`🍽 ${esc(d.lunch)}`);
  if (d.afternoon) L.push(`☀️ ${esc(d.afternoon)}`);
  if (d.dinner)    L.push(`🌙 ${esc(d.dinner)}`);
  if (d.evening)   L.push(`✨ ${esc(d.evening)}`);
  if (d.dayCost)   L.push(`<i>~${d.dayCost} ${cur}</i>`);
  L.push('');
}

const total = Number(raw.estimatedTotal) || 0;
const diff = ctx.budget - total;
L.push('<b>BUDGET</b>');
L.push(`Estimated ~${total} ${cur} of ${ctx.budget} ${cur}`);
L.push(diff >= 0 ? `Margin left ~${diff} ${cur}` : `⚠️ Over by ~${Math.abs(diff)} ${cur}`);
L.push('');

if (Array.isArray(raw.tips) && raw.tips.length) {
  L.push('<b>TIPS</b>');
  raw.tips.slice(0, 5).forEach((t, i) => L.push(`${i + 1}. ${esc(t)}`));
  L.push('');
}

L.push('<i>Estimates only. Confirm opening hours and availability before you go.</i>');

let telegramMessage = L.join('\n');
if (telegramMessage.length > 3900) telegramMessage = telegramMessage.slice(0, 3880) + '\n…\n<i>(trimmed)</i>';

return [{ json: { chatId: ctx.chatId, telegramMessage, estimatedTotal: total, overBudget: diff < 0 } }];
